struct Rule { std::string name; std::function<bool(const Facts&)> when;
              std::function<void(Facts&)> then; bool fired = false; };

std::vector<Rule> rules = {
    {"volume-discount", [](const Facts& f) { return f.units > 100 && f.loyalty > 2; },
                         [](Facts& f) { f.discount = 0.10; }},
    {"vip-shipping",    [](const Facts& f) { return f.vip; },
                         [](Facts& f) { f.freeShipping = true; }},
};

for (auto& r : rules)
    if (!r.fired && r.when(facts)) { r.then(facts); r.fired = true; }

