struct Rule { std::string name; std::function<bool(const Facts&)> when;
              std::function<void(Facts&)> then; bool fired = false; };

std::vector<Rule> rules = {
    {"volume-discount", [](const Facts& f) { return f.units > 100 && f.loyalty > 2; },
                         [](Facts& f) { f.discount = 0.10; }},
    {"vip-shipping",    [](const Facts& f) { return f.vip; },
                         [](Facts& f) { f.freeShipping = true; }},
};

for (auto& r : rules)
    if (!r.fired && r.when(facts)) { r.then(facts); r.fired = true; }

rete::ReteEngine engine;
engine.add_rule("volume-discount")
      .salience(10)
      .when(std::string("?o"), std::string("units"), std::string("bulk"))
      .then([](auto& b, auto& e) {
          e.assert_fact(b.at("?o"), std::string("discount"), std::string("0.10"));
      })
      .build();

engine.assert_fact(std::string("A-1"), std::string("units"), std::string("bulk"));
engine.run();   // agenda + conflict resolution inside the engine
